#include "board.h"
#include "systick.h"
#include "app.h"

int main(void)
{
    if (Board_Init() != GPIO_STATUS_OK)
    {
        while (1)
        {
        }
    }

    SysTick_Init();

    App_Init(SysTick_GetTick());

    while (1)
    {
        uint32_t now = SysTick_GetTick();

        App_Update(now);
    }
}

